void check(bool v,const char* m){if(!v)throw std::runtime_error(m);}
template<class E=std::exception,class F>void rejects(F f){bool caught=false;try{f();}catch(const E&){caught=true;}check(caught,"Expected native aggregation refusal");}
void write(const fs::path& p,const std::string& s){std::ofstream out(p,std::ios::binary);out<<s;out.close();check(bool(out),"Write aggregation fixture");}
std::string read(const fs::path& p){std::ifstream in(p,std::ios::binary);std::ostringstream out;out<<in.rdbuf();check(!in.bad(),"Read aggregation output");return out.str();}
std::shared_ptr<const ExpressionMatrixSource> fixture(const fs::path& root,const std::string& name,std::size_t features,std::size_t observations,const std::string& entries,std::size_t n){
    const auto folder=root/name;fs::create_directory(folder);std::ostringstream f,o;f<<"feature_id\n";o<<"observation_id\n";for(std::size_t i=0;i<features;++i)f<<'G'<<i<<'\n';for(std::size_t i=0;i<observations;++i)o<<'O'<<i<<'\n';write(folder/"features.tsv",f.str());write(folder/"observations.tsv",o.str());write(folder/"matrix.mtx","%%MatrixMarket matrix coordinate integer general\n"+std::to_string(features)+" "+std::to_string(observations)+" "+std::to_string(n)+"\n"+entries);const auto r=import_expression_matrix((folder/"matrix.mtx").u8string(),(folder/"features.tsv").u8string(),(folder/"observations.tsv").u8string(),(folder/"source.qmx").u8string());return open_expression_matrix(r.path,r.file_sha256);
}
class Observed final:public ExpressionMatrixSource {
    std::shared_ptr<const ExpressionMatrixSource> source_;
public:
    mutable std::size_t reads=0,max_features=0;
    std::atomic<bool>* cancel=nullptr;bool malformed=false,stale=false;
    explicit Observed(std::shared_ptr<const ExpressionMatrixSource> p):source_(std::move(p)){}
    const ExpressionMatrixMetadata& metadata()const override{return source_->metadata();}
    const std::string& path()const override{return source_->path();}
    const std::string& file_sha256()const override{return source_->file_sha256();}
    std::size_t payload_bytes()const override{return sizeof(*this)+source_->payload_bytes();}
    void require_current(const std::atomic<bool>* c)const override{if(stale)throw WorkflowInputChanged("Observed stale source");source_->require_current(c);}
    std::vector<ExpressionFeature> feature_page(std::uint64_t f,std::size_t n,std::size_t w,const std::atomic<bool>* c)const override{return source_->feature_page(f,n,w,c);}
    ExpressionFeaturePage search_features(const std::string& q,std::uint64_t f,std::size_t n,std::size_t w,const std::atomic<bool>* c)const override{return source_->search_features(q,f,n,w,c);}
    std::vector<std::string> observation_page(std::uint64_t f,std::size_t n,std::size_t w,const std::atomic<bool>* c)const override{return source_->observation_page(f,n,w,c);}
    std::optional<std::uint64_t> feature_index(const std::string& id,const std::atomic<bool>* c)const override{return source_->feature_index(id,c);}
    std::optional<std::uint64_t> observation_index(const std::string& id,const std::atomic<bool>* c)const override{return source_->observation_index(id,c);}
    std::vector<std::uint64_t> observation_indices(const std::vector<std::string>& ids,std::size_t w,const std::atomic<bool>* c)const override{return source_->observation_indices(ids,w,c);}
    ExpressionSparseBlock read(const ExpressionMatrixSelection& s,std::size_t w,const std::atomic<bool>* c)const override{++reads;max_features=std::max(max_features,s.features.size());auto b=source_->read(s,w,c);if(cancel)cancel->store(true);if(malformed)b.offsets.front()=1;return b;}
};
